ADukeGameMode::ADukeGameMode()
{
	PrimaryActorTick.bCanEverTick = true;
	DefaultPawnClass = nullptr; // the player is spawned by BeginPlay at the start of the city
	PlayerControllerClass = ADukePlayerController::StaticClass();
	HUDClass = ADukeHUD::StaticClass();
}

ADukeGameMode* ADukeGameMode::Get(const UObject* Ctx)
{
	return Ctx ? Cast<ADukeGameMode>(UGameplayStatics::GetGameMode(Ctx)) : nullptr;
}
UDukeGameInstance* ADukeGameMode::Data() const { return Cast<UDukeGameInstance>(GetGameInstance()); }

FVector ADukeGameMode::Ground(float Xm, float Ym) const { return FVector(Xm * 100.f, Ym * 100.f, 0.f); }

FVector ADukeGameMode::DistrictPoint(const FString& Id) const
{
	UDukeGameInstance* GI = Data();
	FVector2D C = GI ? GI->CityCenter : FVector2D::ZeroVector;
	if (GI) if (const FDukeDistrictDef* D = GI->FindDistrict(Id)) C = D->Center;
	const float B = GI ? GI->BlockSize : 60.f;
	const int32 N = GI ? GI->GridN : 12;
	const float X = FMath::Clamp(FMath::RoundToFloat(C.X / B), 0.f, (float)N) * B + 9.f;
	return Ground(X, C.Y);
}

FVector ADukeGameMode::RandomSidewalk(FRandomStream& R) const
{
	UDukeGameInstance* GI = Data();
	const float B = GI->BlockSize;
	const int32 I = R.RandHelper(GI->GridN), J = R.RandHelper(GI->GridN);
	const float T = R.FRand();
	switch (R.RandHelper(4))
	{
	case 0: return Ground(I * B + 9.f, J * B + 9.f + T * (B - 18.f));
	case 1: return Ground((I + 1) * B - 9.f, J * B + 9.f + T * (B - 18.f));
	case 2: return Ground(I * B + 9.f + T * (B - 18.f), J * B + 9.f);
	default: return Ground(I * B + 9.f + T * (B - 18.f), (J + 1) * B - 9.f);
	}
}

ADukeCharacter* ADukeGameMode::SpawnPerson(const FVector& Where, const FString& DefId, int32 Mode, const FLinearColor& Tint)
{
	UDukeGameInstance* GI = Data();
	FActorSpawnParameters P;
	P.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn;
	ADukeCharacter* C = GetWorld()->SpawnActor<ADukeCharacter>(ADukeCharacter::StaticClass(), Where + FVector(0, 0, 100.f), FRotator(0.f, FMath::FRandRange(0.f, 360.f), 0.f), P);
	if (!C) return nullptr;
	C->Mode = (EDukeNpcMode)Mode;
	C->HomeSpot = Where;
	C->ApplyDef(GI ? GI->FindCharacter(DefId) : nullptr, Tint);
	if (C->Mode == EDukeNpcMode::Police || C->Mode == EDukeNpcMode::Hostile || C->Mode == EDukeNpcMode::Target)
	{
		C->MaxHealth = C->Health = C->Mode == EDukeNpcMode::Target ? 160.f : 100.f;
		if (GI && GI->Weapons.Num()) C->GiveWeapon(0, 9999);
	}
	else C->MaxHealth = C->Health = 60.f;
	People.Add(C);
	return C;
}

int32 ADukeGameMode::PickVehicle(bool bPolice, FRandomStream& R) const
{
	UDukeGameInstance* GI = Data();
	TArray<int32> Pool; TArray<float> W; float Sum = 0.f;
	for (int32 i = 0; i < GI->Vehicles.Num(); ++i)
	{
		const FDukeVehicleDef& V = GI->Vehicles[i];
		const bool bCop = V.Class == TEXT("Police") || V.Spawn == TEXT("Police only");
		if (bCop != bPolice || V.Spawn == TEXT("Player garage")) continue;
		const float Wt = V.Spawn == TEXT("Rare traffic") ? 1.f : 3.f;
		Pool.Add(i); W.Add(Wt); Sum += Wt;
	}
	if (!Pool.Num()) return INDEX_NONE;
	float X = R.FRand() * Sum;
	for (int32 k = 0; k < Pool.Num(); ++k) { X -= W[k]; if (X <= 0.f) return Pool[k]; }
	return Pool.Last();
}

ADukeVehicle* ADukeGameMode::SpawnVehicle(const FVector& Where, float Yaw, int32 VehicleIndex, bool bPolice, const FLinearColor& Paint)
{
	UDukeGameInstance* GI = Data();
	FActorSpawnParameters P;
	P.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButDontSpawnIfColliding;
	ADukeVehicle* V = GetWorld()->SpawnActor<ADukeVehicle>(ADukeVehicle::StaticClass(), Where + FVector(0, 0, 90.f), FRotator(0.f, Yaw, 0.f), P);
	if (!V) return nullptr;
	V->ApplyDef(GI && GI->Vehicles.IsValidIndex(VehicleIndex) ? &GI->Vehicles[VehicleIndex] : nullptr, Paint, bPolice);
	Vehicles.Add(V);
	return V;
}

void ADukeGameMode::SpawnPopulation()
{
	UDukeGameInstance* GI = Data();
	FRandomStream R(1337);
	const float B = GI->BlockSize;
	const int32 N = GI->GridN;
	const float Scale = N / 14.f;
	auto Density = [](const FString& S) { return S == TEXT("Light") ? 0.55f : (S == TEXT("Heavy") ? 1.5f : 1.f); };
	static const FLinearColor Paints[] = { FLinearColor(0.6f,0.02f,0.02f), FLinearColor(0.02f,0.03f,0.05f), FLinearColor(0.8f,0.8f,0.8f), FLinearColor(0.3f,0.31f,0.33f),
		FLinearColor(0.02f,0.08f,0.35f), FLinearColor(0.9f,0.4f,0.05f), FLinearColor(0.9f,0.7f,0.05f), FLinearColor(0.85f,0.25f,0.4f) };

	// civilians use Civilian-role models first, then other supporting cast
	TArray<FString> CrowdModels;
	for (const FDukeCharacterDef& C : GI->Characters) if (C.Role == TEXT("Civilian") && !C.Mesh.IsEmpty()) CrowdModels.Add(C.Id);
	if (!CrowdModels.Num()) for (const FDukeCharacterDef& C : GI->Characters) if (C.Role != TEXT("Protagonist") && C.Role != TEXT("Antagonist") && !C.Mesh.IsEmpty()) CrowdModels.Add(C.Id);

	const int32 Peds = FMath::RoundToInt(70 * Density(GI->Crowds) * Scale);
	for (int32 k = 0; k < Peds; ++k)
	{
		const FVector P = RandomSidewalk(R);
		const FString Model = CrowdModels.Num() ? CrowdModels[R.RandHelper(CrowdModels.Num())] : FString();
		if (ADukeCharacter* C = SpawnPerson(P, Model, (int32)EDukeNpcMode::Civilian, FLinearColor(R.FRand(), R.FRand(), R.FRand())))
		{
			C->NavI = FMath::Clamp(FMath::FloorToInt(P.X / (B * 100.f)), 0, N - 1);
			C->NavJ = FMath::Clamp(FMath::FloorToInt(P.Y / (B * 100.f)), 0, N - 1);
			C->Corner = R.RandHelper(4); C->CornerDir = R.RandBool() ? 1 : -1;
			C->DisplayName.Empty();
		}
	}
	const int32 Traffic = FMath::RoundToInt(45 * Density(GI->Traffic) * Scale);
	for (int32 k = 0, Tries = 0; k < Traffic && Tries < Traffic * 4; ++Tries)
	{
		const int32 D = R.RandHelper(4);
		const FIntPoint Node(R.RandHelper(N + 1), R.RandHelper(N + 1));
		const FIntPoint Prev = Node - GDir[D];
		if (Prev.X < 0 || Prev.Y < 0 || Prev.X > N || Prev.Y > N) continue;
		const float Lane = R.RandBool() ? 175.f : 525.f;
		const float T = R.FRandRange(0.2f, 0.7f);
		const FVector2D Pos = FMath::Lerp(FVector2D(Prev) * B * 100.f, FVector2D(Node) * B * 100.f, T) + FVector2D(-GDir[D].Y, GDir[D].X) * Lane;
		const bool bPolice = GI->bWanted && R.FRand() < 0.08f;
		const int32 VI = PickVehicle(bPolice, R);
		if (ADukeVehicle* V = SpawnVehicle(FVector(Pos.X, Pos.Y, 0.f), FMath::RadiansToDegrees(FMath::Atan2((float)GDir[D].Y, (float)GDir[D].X)), VI, bPolice, Paints[R.RandHelper(8)]))
		{
			V->StartTraffic(D, Node, Lane);
			++k;
		}
	}
	for (const FDukeProp& P : GI->Parked)
	{
		if (R.FRand() < 0.5f) continue;
		SpawnVehicle(Ground(P.Pos.X, P.Pos.Y), R.RandBool() ? 90.f : -90.f, PickVehicle(false, R), false, Paints[R.RandHelper(8)]);
	}
}

void ADukeGameMode::BeginPlay()
{
	Super::BeginPlay();
	UDukeGameInstance* GI = Data();
	if (!GI || !GI->bLoaded)
	{
		Flash(TEXT("DATA MISSING"), GI ? GI->LoadError : TEXT("Game instance is not UDukeGameInstance"), 9999.f);
		return;
	}
	City = GetWorld()->SpawnActor<ADukeCityBuilder>(ADukeCityBuilder::StaticClass(), FTransform::Identity);
	if (City) City->Build(GI);
	Cash = GI->StartCash;
	GameHour = GI->StartTime;

	// the player
	const float B = GI->BlockSize;
	const FVector Start = Ground(FMath::RoundToFloat(GI->CityCenter.X / B) * B + 9.f, FMath::FloorToFloat(GI->CityCenter.Y / B) * B + B * 0.5f + 4.f);
	ADukeCharacter* Player = GetWorld()->SpawnActorDeferred<ADukeCharacter>(ADukeCharacter::StaticClass(), FTransform(FRotator::ZeroRotator, Start + FVector(0, 0, 120.f)), nullptr, nullptr, ESpawnActorCollisionHandlingMethod::AdjustIfPossibleButAlwaysSpawn);
	if (Player)
	{
		Player->bIsPlayer = true;
		Player->AutoPossessAI = EAutoPossessAI::Disabled;
		Player->FinishSpawning(FTransform(FRotator::ZeroRotator, Start + FVector(0, 0, 120.f)));
		const FDukeCharacterDef* Hero = GI->Protagonist();
		Player->ApplyDef(Hero, FLinearColor(0.1f, 0.6f, 0.6f));
		Player->MaxHealth = Player->Health = GI->PlayerHealth;
		Player->Armor = GI->bArmor ? 50.f : 0.f;
		if (GI->Weapons.Num()) Player->GiveWeapon(0, GI->Weapons[0].Magazine * 4);
		PlayerChar = Player;
		if (APlayerController* PC = GetWorld()->GetFirstPlayerController())
		{
			PC->Possess(Player);
			if (ADukePlayerController* DPC = Cast<ADukePlayerController>(PC)) DPC->SetDriving(false);
		}
		for (int32 i = 0, k = 0; i < GI->Vehicles.Num(); ++i)
			if (GI->Vehicles[i].Spawn == TEXT("Player garage"))
				SpawnVehicle(Start + FVector(-350.f, 600.f + 650.f * k++, 0.f), 90.f, i, false, FLinearColor::White);
	}
	SpawnPopulation();
	SetupMissionGiver();
	if (City) City->SetTime(GameHour, GI->Weather == TEXT("Stormy"));
	bTitleCard = true;
	NextIntroLine = GetWorld()->GetTimeSeconds() + 6.f;
}

void ADukeGameMode::SkipIntro()
{
	if (bTitleCard) { bTitleCard = false; NextIntroLine = GetWorld()->GetTimeSeconds(); return; }
	UDukeGameInstance* GI = Data();
	if (GI && IntroLine < GI->Intro.Num()) { IntroLine = GI->Intro.Num(); SubtitleUntil = 0.f; }
}

void ADukeGameMode::TickIntro()
{
	UDukeGameInstance* GI = Data();
	const float Now = GetWorld()->GetTimeSeconds();
	if (bTitleCard && Now > NextIntroLine) { bTitleCard = false; NextIntroLine = Now; }
	if (bTitleCard || !GI || IntroLine >= GI->Intro.Num() || Now < NextIntroLine) return;
	const FDukeIntroLine& L = GI->Intro[IntroLine++];
	const float Dur = FMath::Clamp(L.Text.Len() / 14.f, 2.5f, 7.f);
	Say(L.Speaker, L.Text, Dur);
	NextIntroLine = Now + Dur + 0.3f;
}

void ADukeGameMode::Say(const FString& Speaker, const FString& Text, float Seconds)
{
	SubtitleSpeaker = Speaker; SubtitleText = Text; SubtitleUntil = GetWorld()->GetTimeSeconds() + Seconds;
}
void ADukeGameMode::Flash(const FString& Big, const FString& Small, float Seconds)
{
	BigText = Big; SmallText = Small; BigTextUntil = GetWorld()->GetTimeSeconds() + Seconds;
}

ADukeVehicle* ADukeGameMode::FindVehicleNear(const FVector& P, float Radius) const
{
	ADukeVehicle* Best = nullptr; float BD = Radius;
	for (ADukeVehicle* V : Vehicles)
	{
		if (!V || V->Driver.IsValid()) continue;
		const float D = FVector::Dist2D(V->GetActorLocation(), P);
		if (D < BD) { BD = D; Best = V; }
	}
	return Best;
}

void ADukeGameMode::EnterVehicle(ADukeCharacter* Who, ADukeVehicle* V)
{
	if (!Who || !V || V->Driver.IsValid()) return;
	if (V->bPolice) ReportCrime(2, V->GetActorLocation());
	else if (V->bAI) { for (const TWeakObjectPtr<ADukeVehicle>& P : PoliceCars) if (P.IsValid() && FVector::Dist(P->GetActorLocation(), V->GetActorLocation()) < 4000.f) { ReportCrime(1, V->GetActorLocation()); break; } }
	V->bAI = false; V->bChase = false; V->bSiren = false;
	V->Driver = Who;
	Who->SetActorHiddenInGame(true);
	Who->SetActorEnableCollision(false);
	Who->AttachToActor(V, FAttachmentTransformRules::SnapToTargetNotIncludingScale);
	if (ADukePlayerController* PC = Cast<ADukePlayerController>(GetWorld()->GetFirstPlayerController()))
	{
		PC->Possess(V);
		PC->SetDriving(true);
	}
}

void ADukeGameMode::ExitVehicle(ADukeVehicle* V)
{
	if (!V || !V->Driver.IsValid()) return;
	ADukeCharacter* Who = V->Driver.Get();
	V->Driver = nullptr;
	Who->DetachFromActor(FDetachmentTransformRules::KeepWorldTransform);
	const FVector Side = -V->GetActorRightVector() * (V->Box->GetScaledBoxExtent().Y + 80.f);
	Who->SetActorLocation(V->GetActorLocation() + Side + FVector(0, 0, 60.f), false, nullptr, ETeleportType::TeleportPhysics);
	Who->SetActorRotation(FRotator(0.f, V->GetActorRotation().Yaw, 0.f));
	Who->SetActorHiddenInGame(false);
	Who->SetActorEnableCollision(true);
	if (ADukePlayerController* PC = Cast<ADukePlayerController>(GetWorld()->GetFirstPlayerController()))
	{
		PC->Possess(Who);
		PC->SetControlRotation(FRotator(-10.f, V->GetActorRotation().Yaw, 0.f));
		PC->SetDriving(false);
	}
}

void ADukeGameMode::PlayerTalk(ADukeCharacter* Who)
{
	if (!Who) return;
	if (bTitleCard || SubtitleUntil > GetWorld()->GetTimeSeconds()) { SkipIntro(); }
	ADukeCharacter* Best = nullptr; float BD = 280.f;
	for (ADukeCharacter* C : People)
	{
		if (!C || C->bDead || C->DisplayName.IsEmpty()) continue;
		const float D = FVector::Dist2D(C->GetActorLocation(), Who->GetActorLocation());
		if (D < BD) { BD = D; Best = C; }
	}
	if (!Best) return;
	if (Best == Giver.Get() && MissionState == EDukeMissionState::Available) { StartMission(); return; }
	if (Best->Lines.Num()) Say(Best->DisplayName, Best->Lines[FMath::RandHelper(Best->Lines.Num())], 4.f);
	else Say(Best->DisplayName, TEXT("Not now. I've got things to do."), 3.f);
}

void ADukeGameMode::OnCharacterDied(ADukeCharacter* Who, AController* Killer)
{
	if (Who == PlayerChar)
	{
		Flash(TEXT("WASTED"), FString::Printf(TEXT("Hospital bill: $%d"), FMath::Min(Cash, FMath::Max(100, Cash / 10))), 5.f);
		Cash -= FMath::Min(Cash, FMath::Max(100, Cash / 10));
		RespawnAt = GetWorld()->GetTimeSeconds() + 5.f;
		return;
	}
	People.Remove(Who);
	Who->SetLifeSpan(25.f);
}

void ADukeGameMode::ReportCrime(int32 Stars, const FVector& Where)
{
	UDukeGameInstance* GI = Data();
	if (!GI || !GI->bWanted || Stars <= 0) return;
	const int32 Before = GetWanted();
	Wanted = FMath::Min((float)GI->MaxWanted, FMath::Max(Wanted, (float)Before) + Stars);
	LastSeenByPolice = GetWorld()->GetTimeSeconds();
}

void ADukeGameMode::TickWanted(float Dt)
{
	UDukeGameInstance* GI = Data();
	APawn* P = UGameplayStatics::GetPlayerPawn(this, 0);
	if (!GI || !P) return;
	const float Now = GetWorld()->GetTimeSeconds();
	PoliceCars.RemoveAll([](const TWeakObjectPtr<ADukeVehicle>& V) { return !V.IsValid(); });
	PoliceFoot.RemoveAll([](const TWeakObjectPtr<ADukeCharacter>& C) { return !C.IsValid() || C->bDead; });
	const int32 Stars = GetWanted();
	if (Stars <= 0)
	{
		for (const TWeakObjectPtr<ADukeVehicle>& V : PoliceCars) if (V->bChase) { V->bChase = false; V->bSiren = false; V->SetLifeSpan(20.f); }
		return;
	}
	// police that can see the player keep the heat on
	bool bSeen = false;
	for (const TWeakObjectPtr<ADukeVehicle>& V : PoliceCars) if (FVector::Dist(V->GetActorLocation(), P->GetActorLocation()) < 9000.f) bSeen = true;
	for (const TWeakObjectPtr<ADukeCharacter>& C : PoliceFoot) if (FVector::Dist(C->GetActorLocation(), P->GetActorLocation()) < 6000.f) bSeen = true;
	if (bSeen) LastSeenByPolice = Now;
	else if (Now - LastSeenByPolice > 18.f) { Wanted = FMath::Max(0.f, (float)Stars - 1.f); LastSeenByPolice = Now; }
	// dispatch
	PoliceSpawnCooldown -= Dt;
	const int32 WantCars = FMath::Min(1 + Stars, 5);
	if (PoliceCars.Num() < WantCars && PoliceSpawnCooldown <= 0.f)
	{
		PoliceSpawnCooldown = 4.f;
		FRandomStream R(FMath::Rand());
		const float B = GI->BlockSize * 100.f;
		const FVector Pp = P->GetActorLocation();
		const float Ang = R.FRandRange(0.f, 2.f * PI);
		const FVector Want = Pp + FVector(FMath::Cos(Ang), FMath::Sin(Ang), 0.f) * R.FRandRange(14000.f, 22000.f);
		const FIntPoint Node(FMath::Clamp(FMath::RoundToInt(Want.X / B), 0, GI->GridN), FMath::Clamp(FMath::RoundToInt(Want.Y / B), 0, GI->GridN));
		if (ADukeVehicle* V = SpawnVehicle(FVector(Node.X * B, Node.Y * B, 0.f), FMath::RadiansToDegrees(FMath::Atan2(Pp.Y - Node.Y * B, Pp.X - Node.X * B)), PickVehicle(true, R), true, FLinearColor(0.85f, 0.85f, 0.88f)))
		{
			V->bChase = true; V->bSiren = true;
			PoliceCars.Add(V);
		}
	}
	// officers bail out near a player on foot
	if (Cast<ADukeCharacter>(P) && PoliceFoot.Num() < Stars * 2)
	{
		for (const TWeakObjectPtr<ADukeVehicle>& V : PoliceCars)
		{
			if (!V->bChase || V->Speed > 300.f || FVector::Dist(V->GetActorLocation(), P->GetActorLocation()) > 2200.f || V->Tags.Contains(TEXT("Unloaded"))) continue;
			V->Tags.Add(TEXT("Unloaded"));
			FString CopModel;
			for (const FDukeCharacterDef& C : GI->Characters) if (C.Role == TEXT("Police officer") && !C.Mesh.IsEmpty()) { CopModel = C.Id; break; }
			for (int32 s = -1; s <= 1; s += 2)
				if (ADukeCharacter* Cop = SpawnPerson(V->GetActorLocation() + V->GetActorRightVector() * s * 250.f, CopModel, (int32)EDukeNpcMode::Police, FLinearColor(0.05f, 0.08f, 0.25f)))
				{
					Cop->DisplayName.Empty();
					PoliceFoot.Add(Cop);
				}
		}
	}
}

void ADukeGameMode::PlaceMarker(const FVector& Where, bool bShow)
{
	if (!Marker)
	{
		Marker = GetWorld()->SpawnActor<AActor>(AActor::StaticClass(), FTransform::Identity);
		USceneComponent* Root = NewObject<USceneComponent>(Marker);
		Marker->SetRootComponent(Root);
		Root->RegisterComponent();
		UStaticMesh* Cyl = LoadObject<UStaticMesh>(nullptr, TEXT("/Engine/BasicShapes/Cylinder.Cylinder"));
		UDukeGameInstance* GI = Data();
		UMaterialInterface* Base = (GI && !GI->ColorMaterial.IsEmpty()) ? LoadObject<UMaterialInterface>(nullptr, *GI->ColorMaterial) : nullptr;
		if (!Base) Base = LoadObject<UMaterialInterface>(nullptr, TEXT("/Engine/BasicShapes/BasicShapeMaterial.BasicShapeMaterial"));
		for (int32 k = 0; k < 2; ++k)
		{
			UStaticMeshComponent* C = NewObject<UStaticMeshComponent>(Marker);
			C->SetupAttachment(Root);
			C->SetStaticMesh(Cyl);
			C->SetCollisionEnabled(ECollisionEnabled::NoCollision);
			C->SetCastShadow(false);
			C->SetRelativeScale3D(k == 0 ? FVector(3.6f, 3.6f, 0.15f) : FVector(0.35f, 0.35f, 60.f));
			C->SetRelativeLocation(FVector(0.f, 0.f, k == 0 ? 10.f : 3000.f));
			if (Base)
			{
				UMaterialInstanceDynamic* M = UMaterialInstanceDynamic::Create(Base, Marker);
				M->SetVectorParameterValue(TEXT("Color"), FLinearColor(1.f, 0.7f, 0.1f));
				M->SetScalarParameterValue(TEXT("Emissive"), 8.f);
				C->SetMaterial(0, M);
			}
			C->RegisterComponent();
		}
	}
	Marker->SetActorHiddenInGame(!bShow);
	Marker->SetActorLocation(FVector(Where.X, Where.Y, 0.f));
	ObjectiveLocation = Where;
	bHasObjectiveLocation = bShow;
}

void ADukeGameMode::SetupMissionGiver()
{
	UDukeGameInstance* GI = Data();
	if (!GI) return;
	if (!GI->Missions.IsValidIndex(MissionIndex))
	{
		Objective = GI->Missions.Num() ? TEXT("Story complete. The city is yours.") : TEXT("Explore the city.");
		PlaceMarker(FVector::ZeroVector, false);
		return;
	}
	const FDukeMissionDef& M = GI->Missions[MissionIndex];
	FVector Where = MissionIndex == 0 && PlayerChar ? PlayerChar->GetActorLocation() + FVector(900.f, 300.f, 0.f) : DistrictPoint(M.DistrictId);
	if (!Giver.IsValid() || Giver->DefId != M.GiverId)
	{
		if (Giver.IsValid()) Giver->Mode = EDukeNpcMode::Civilian;
		Giver = SpawnPerson(Where, M.GiverId, (int32)EDukeNpcMode::Giver, FLinearColor(0.9f, 0.7f, 0.2f));
	}
	else Giver->HomeSpot = Where;
	const FDukeCharacterDef* GD = GI->FindCharacter(M.GiverId);
	Objective = FString::Printf(TEXT("Meet %s to start \"%s\""), GD ? *GD->Name : TEXT("your contact"), *M.Name);
	PlaceMarker(Giver.IsValid() ? Giver->GetActorLocation() : Where, true);
	MissionState = EDukeMissionState::Available;
}

void ADukeGameMode::StartMission()
{
	UDukeGameInstance* GI = Data();
	if (!GI || !GI->Missions.IsValidIndex(MissionIndex)) return;
	const FDukeMissionDef& M = GI->Missions[MissionIndex];
	MissionState = EDukeMissionState::Active;
	if (Giver.IsValid()) Say(Giver->DisplayName, M.Briefing, FMath::Clamp(M.Briefing.Len() / 14.f, 3.f, 8.f));
	Flash(M.Name.ToUpper(), TEXT(""), 3.f);
	const FString District = GI->FindDistrict(M.DistrictId) ? GI->FindDistrict(M.DistrictId)->Name : GI->CityName;
	FVector Where = DistrictPoint(M.DistrictId);
	DeliverStage = 0;
	if (M.Objective == TEXT("Drive to location"))
	{
		Objective = FString::Printf(TEXT("Get to %s%s"), *District, M.Target.IsEmpty() ? TEXT("") : *(TEXT(" - ") + M.Target));
		PlaceMarker(Where, true);
	}
	else if (M.Objective == TEXT("Deliver vehicle"))
	{
		FRandomStream R(MissionIndex * 77 + 5);
		int32 VI = PickVehicle(false, R);
		for (int32 i = 0; i < GI->Vehicles.Num(); ++i) if (!M.Target.IsEmpty() && M.Target.Contains(GI->Vehicles[i].Name)) VI = i;
		const float B = GI->BlockSize * 100.f;
		const FVector Road(FMath::RoundToFloat(Where.X / B) * B + 175.f, Where.Y, 0.f);
		MissionCar = SpawnVehicle(Road, 90.f, VI, false, FLinearColor(0.9f, 0.9f, 0.9f));
		if (MissionCar.IsValid()) MissionCar->bMissionVehicle = true;
		DropOff = Giver.IsValid() ? Giver->GetActorLocation() : (PlayerChar ? PlayerChar->GetActorLocation() : FVector::ZeroVector);
		Objective = FString::Printf(TEXT("Steal the %s in %s"), MissionCar.IsValid() ? *MissionCar->DisplayName : TEXT("car"), *District);
		PlaceMarker(MissionCar.IsValid() ? MissionCar->GetActorLocation() : Where, true);
	}
	else if (M.Objective == TEXT("Eliminate target"))
	{
		FString TargetDef;
		for (const FDukeCharacterDef& C : GI->Characters) if (!M.Target.IsEmpty() && M.Target.Contains(C.Name)) TargetDef = C.Id;
		TargetChar = SpawnPerson(Where + FVector(0.f, 400.f, 0.f), TargetDef, (int32)EDukeNpcMode::Target, FLinearColor(0.7f, 0.1f, 0.1f));
		if (TargetChar.IsValid() && TargetChar->DisplayName.IsEmpty()) TargetChar->DisplayName = M.Target.IsEmpty() ? TEXT("Target") : M.Target;
		for (int32 g = 0; g < 2; ++g)
			if (ADukeCharacter* Guard = SpawnPerson(Where + FVector(250.f * (g ? 1 : -1), 600.f, 0.f), FString(), (int32)EDukeNpcMode::Hostile, FLinearColor(0.15f, 0.15f, 0.15f)))
			{ Guard->DisplayName.Empty(); MissionExtras.Add(Guard); }
		Objective = FString::Printf(TEXT("Eliminate %s in %s"), TargetChar.IsValid() ? *TargetChar->DisplayName : TEXT("the target"), *District);
		PlaceMarker(Where, true);
	}
	else if (M.Objective == TEXT("Collect item"))
	{
		Objective = FString::Printf(TEXT("Collect %s in %s"), M.Target.IsEmpty() ? TEXT("the package") : *M.Target, *District);
		PlaceMarker(Where + FVector(0.f, 900.f, 0.f), true);
	}
	else // Escape the police
	{
		Wanted = FMath::Max(Wanted, 3.f);
		LastSeenByPolice = GetWorld()->GetTimeSeconds();
		Objective = TEXT("Lose the police");
		PlaceMarker(FVector::ZeroVector, false);
	}
}

void ADukeGameMode::CompleteMission()
{
	UDukeGameInstance* GI = Data();
	if (!GI || !GI->Missions.IsValidIndex(MissionIndex)) return;
	const FDukeMissionDef& M = GI->Missions[MissionIndex];
	Cash += M.Reward;
	Flash(TEXT("MISSION PASSED"), FString::Printf(TEXT("+$%d"), M.Reward), 5.f);
	for (TWeakObjectPtr<ADukeCharacter>& C : MissionExtras) if (C.IsValid()) C->SetLifeSpan(30.f);
	MissionExtras.Empty();
	if (MissionCar.IsValid()) MissionCar->bMissionVehicle = false;
	MissionCar = nullptr; TargetChar = nullptr;
	++MissionIndex;
	SetupMissionGiver();
}

void ADukeGameMode::TickMission(float Dt)
{
	UDukeGameInstance* GI = Data();
	APawn* P = UGameplayStatics::GetPlayerPawn(this, 0);
	if (!GI || !P || MissionState != EDukeMissionState::Active || !GI->Missions.IsValidIndex(MissionIndex)) { if (MissionState == EDukeMissionState::Available && Giver.IsValid()) PlaceMarker(Giver->GetActorLocation(), true); return; }
	const FDukeMissionDef& M = GI->Missions[MissionIndex];
	const FVector Pp = P->GetActorLocation();
	if (M.Objective == TEXT("Drive to location") || M.Objective == TEXT("Collect item"))
	{
		if (FVector::Dist2D(Pp, ObjectiveLocation) < (M.Objective == TEXT("Collect item") ? 300.f : 900.f)) CompleteMission();
	}
	else if (M.Objective == TEXT("Deliver vehicle"))
	{
		if (!MissionCar.IsValid()) { CompleteMission(); return; }
		const bool bDriving = MissionCar->Driver.IsValid();
		if (DeliverStage == 0 && bDriving) { DeliverStage = 1; Objective = TEXT("Deliver the car"); }
		PlaceMarker(DeliverStage == 0 ? MissionCar->GetActorLocation() : DropOff, true);
		if (DeliverStage == 1 && FVector::Dist2D(MissionCar->GetActorLocation(), DropOff) < 900.f) CompleteMission();
	}
	else if (M.Objective == TEXT("Eliminate target"))
	{
		if (!TargetChar.IsValid() || TargetChar->bDead) CompleteMission();
		else PlaceMarker(TargetChar->GetActorLocation(), true);
	}
	else if (GetWanted() == 0) CompleteMission();
}

void ADukeGameMode::Tick(float Dt)
{
	Super::Tick(Dt);
	UDukeGameInstance* GI = Data();
	if (!GI || !GI->bLoaded) return;
	const float Now = GetWorld()->GetTimeSeconds();
	GameHour = FMath::Fmod(GameHour + Dt / 60.f, 24.f);
	static float NextSky = 0.f;
	if (City && Now > NextSky) { City->SetTime(GameHour, GI->Weather == TEXT("Stormy")); NextSky = Now + 0.5f; }
	TickIntro();
	TickWanted(Dt);
	TickMission(Dt);
	if (RespawnAt > 0.f && Now > RespawnAt && PlayerChar)
	{
		RespawnAt = -1.f; Wanted = 0.f;
		PlayerChar->Respawn(Ground(GI->CityCenter.X, GI->CityCenter.Y) + FVector(0.f, 900.f, 0.f));
	}
	People.RemoveAll([](const TObjectPtr<ADukeCharacter>& C) { return !IsValid(C); });
	Vehicles.RemoveAll([](const TObjectPtr<ADukeVehicle>& V) { return !IsValid(V); });

	// contextual prompt
	Prompt.Empty();
	APawn* P = UGameplayStatics::GetPlayerPawn(this, 0);
	if (ADukeCharacter* C = Cast<ADukeCharacter>(P))
	{
		for (ADukeCharacter* O : People)
			if (O && !O->bDead && !O->DisplayName.IsEmpty() && FVector::Dist2D(O->GetActorLocation(), C->GetActorLocation()) < 280.f)
			{ Prompt = (O == Giver.Get() && MissionState == EDukeMissionState::Available) ? FString::Printf(TEXT("E  Start mission with %s"), *O->DisplayName) : FString::Printf(TEXT("E  Talk to %s"), *O->DisplayName); break; }
		if (Prompt.IsEmpty() && FindVehicleNear(C->GetActorLocation(), 450.f)) Prompt = TEXT("F  Enter vehicle");
	}
}
